def get_api_data(url, params=None, timeout=2, proxies=None):
    """
    发送GET请求并获取JSON数据。

    :param url: API的URL地址
    :param params: 查询参数
    :param timeout: 请求超时时间（秒）
    :return: JSON响应数据
    """
    global proxies_
    print("[API]正在调用API...")
    proxies2 = get_environment_proxy()
    if proxies:
        print(f"使用代理: {proxies}")
        proxies2 = proxies
    elif proxies2:
        print(f"检测到代理: {proxies2}")
    else:
        print("未配置代理")
    try:
        response = requests.get(url, params=params, timeout=timeout, proxies=proxies2)
        response.raise_for_status()  # 如果响应状态码不是200，抛出HTTPError异常
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"API请求失败, 尝试默认代理重连: {e}")
        try:
            response = requests.get(url, params=params, timeout=timeout, proxies=proxies_)
            response.raise_for_status()  # 如果响应状态码不是200，抛出HTTPError异常
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"API请求失败: {e}")
            return


def post_api_data(url, data=None, json_data=None, timeout=2, proxies=None):
    """
    发送POST请求并获取JSON数据。

    :param url: API的URL地址
    :param data: 表单数据
    :param json_data: JSON数据
    :param timeout: 请求超时时间（秒）
    :return: JSON响应数据
    """
    global proxies_
    print("[API]正在调用API...")
    proxies2 = get_environment_proxy()
    if proxies:
        print(f"使用代理: {proxies}")
        proxies2 = proxies
    elif proxies2:
        print(f"检测到代理: {proxies2}")
    else:
        print("未配置代理")
    try:
        response = requests.post(url, data=data, json=json_data, timeout=timeout, proxies=proxies2)
        response.raise_for_status()  # 如果响应状态码不是200，抛出HTTPError异常
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"API请求失败, 尝试默认代理重连: {e}")
        try:
            response = requests.post(url, data=data, json=json_data, timeout=timeout, proxies=proxies_)
            response.raise_for_status()  # 如果响应状态码不是200，抛出HTTPError异常
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"API请求失败: {e}")
            return


def save_json_to_file(data, filename):
    """
    将JSON数据保存到本地文件。

    :param data: 要保存的JSON数据
    :param filename: 文件名
    """
    with open(filename, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=4)
    print(f"API数据已保存: {filename}")


def create_folder(folder_path):
    try:
        os.makedirs(folder_path)
        print(f"文件夹 '{folder_path}' 创建成功")
    except FileExistsError:
        print(f"文件夹 '{folder_path}' 已经存在")


