def play_audio(file_path, name, loops=-1):  # 程序能够续接音效、BGM、HO和FX #程序会显示当前正在播放的BGM名称
    print("开始播放：" + name + " → " + file_path)
    if file_path:
        pygame.mixer.init()
        # pygame.mixer.music.load(file_path)
        # pygame.mixer.music.play(loops = loops)
        sound = pygame.mixer.Sound(file_path)
        sound.play(loops=loops)
        if loops == -1:
            audio_list[name] = sound


def get_environment_proxy():
    try:
        internet_settings = winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                                           r'Software\Microsoft\Windows\CurrentVersion\Internet Settings')
        proxy_enable, regtype = winreg.QueryValueEx(internet_settings, 'ProxyEnable')
        proxy_server, regtype = winreg.QueryValueEx(internet_settings, 'ProxyServer')

        if proxy_enable:
            return {
                "http": proxy_server,
                "https": proxy_server
            }
    except Exception as e:
        print(f"无法获取代理设置: {e}")
        return None
    return None


def kill_audio(name):
    global audio_list
    print("停止播放：" + name)
    audio_list[name].stop()
    audio_list.pop(name)


