class ChatApp:
    def __init__(self, root):
        self.root = root
        self.autoSave_firstTime()
        # 一系列字符串
        global title_name
        self.root.title(title_name)
        # 设置图标
        self.root.iconbitmap("AppSettings/icon.ico")

        # 其他窗口内容
        # self.label = tk.Label(root, text="Hello, Tkinter!")

        # 绑定回车键和Alt+回车键
        root.bind("<Return>", lambda event: self.send_message(self.current_role.get()))
        root.bind("<Control-s>", lambda event: self.quickSave())
        root.bind("<Alt-Return>", lambda event: self.insert_newline())
        root.bind("<Control-Return>", lambda event: self.newline_on_ctrl_enter(event))
