        self.role_count = self.role_count
        new_role = f"PL {len(self.roles) - 1}"
        self.roles.append(new_role)
        self.canvas_icon_animate[new_role] = tk.Canvas(self.root, width=20, height=20)
        self.image_references_on_Avatar[new_role] = []
