                lines = chat_log_content.split('\n')
                # 用于存放行号的列表
                # 遍历每一行，查找开头是 "[" 的行、查找开头是【展示图片】的行
                merged_speak = []
                speak_content = ""
                last_speak_content = ""
                now_name = ""
                last_name = ""
                merged_speak_del = []
                for i, line in enumerate(lines):
                    if line[0] == "[":
                        name = re.findall(r'\[([^\]]*)\]', line)
                        # 如果说话人在角色列表，在句尾加语音合成标记"{*}"
