            for status2 in status_list_name:
                if status2 in self.status_icon:
                    _, extension = os.path.splitext(self.status_icon[status2]["_path"])
                    filename, dot = os.path.splitext(os.path.basename(self.status_icon[status2]["_path"]))
                    if extension == ".apng" or extension == ".APNG":
                        avatar_path = self.apng_to_gif(self.status_icon[status2]["_path"], _ + ".gif")
                    elif extension == ".gif" or extension == ".GIF":
                        image = Image.open(self.status_icon[status2]["_path"])
                        # 获取图像的宽和高
                        width, height = image.size
                        self.canvas_animate_icon2 = tk.Canvas(self.ani_frame_icon[role], width=50, height=50)
                        self.canvas_animate_icon2.grid(row=3, column=2, padx=5, pady=5, sticky="nsew")
