class DiceRollDialog(simpledialog.Dialog):
    def __init__(self, parent, title=None, tree=None):
        self.tree = tree
        super().__init__(parent, title)
        # self.ChatApp = chat_app_instance

    def randomize_info(self):
        global room_info_search
        global room_info_list
        if len(room_info_list) > 0 and len(room_info_search) > 0:
            room_list = []
            for room, value in room_info_search.items():
                room_info_search[room]["信息"].clear()
                room_list.append(room)
            for content, type in room_info_list.items():
                room_info_search[random.choice(room_list)]["信息"][content] = type

    def upload_info(self):
        global room_info_list
        room_info_list[self.content_var.get()] = self.info_type_var.get()
        self.info_type_var.set("")
        self.content_var.set("")
        self.randomize_info()

    def clear(self):
        global room_info_search
        global room_info_list
        room_info_search.clear()
        room_info_list.clear()

    def upload_room(self, master):
        global room_info_search
        room_info_search[self.roomname_var.get()] = {"类型": self.room_var.get(), "扩散": int(self.kuosan_var.get()),
                                                     "信息": {}}
        self.room_var.set("")
        self.roomname_var.set("")
        self.kuosan_var.set("")
        self.searched_room_name_list = []
        for roomnames, value in room_info_search.items():
            self.searched_room_name_list.append(roomnames)
        self.searched_room_name = ttk.Combobox(master, textvariable=self.searched_room_name_var,
                                               values=self.searched_room_name_list)
        self.searched_room_name.grid(row=11, column=1, sticky="e")
        self.randomize_info()

    def search_room(self):
        global room_info_search
        global room_info_list
        if self.searched_room_name_var.get() != "" and len(room_info_list) > 0:
            self.result_text_.delete("1.0", tk.END)
            if self.adjust_var.get() == "":
                self.adjust_var.set("0")
            if len(room_info_search[self.searched_room_name_var.get()]["信息"]) >= random.randint(1, room_info_search[
                                                                                                       self.searched_room_name_var.get()][
                                                                                                       "扩散"] - int(
                self.adjust_var.get())):
                _list = []
                for i, c in room_info_search[self.searched_room_name_var.get()]["信息"].items():
                    _list.append(i)
                infocontent = random.choice(_list)
                infotype = room_info_search[self.searched_room_name_var.get()]["信息"][infocontent]

                room_info_search[self.searched_room_name_var.get()]["信息"].pop(infocontent)
                room_info_list.pop(infocontent)
                self.result_text_.insert(tk.END,
                                         f"发现了一个[{infotype}]！：{infocontent}\n(房间内余{len(room_info_search[self.searched_room_name_var.get()]['信息'])}，共余{len(room_info_list)})。")
            else:
                self.result_text_.insert(tk.END,
                                         f"本次搜查未找到任何信息！(房间内余{len(room_info_search[self.searched_room_name_var.get()]['信息'])}，共余{len(room_info_list)})！")
                room_info_search[self.searched_room_name_var.get()]["扩散"] -= 1
        elif self.searched_room_name_var.get() == "":
            self.result_text_.insert(tk.END, "\n请选择房间！")
        elif len(room_info_list) <= 0:
            self.result_text_.insert(tk.END, f"\n所有信息已找到(余{len(room_info_list)})！")

